SELECT room_id
FROM CHAT_ROOM
WHERE type = #{type}
AND target_code = #{targetCode}
AND (
(REQUESTER_CODE = #{requesterCode} AND RESPONDER_CODE = #{responderCode})
OR (REQUESTER_CODE = #{responderCode} AND RESPONDER_CODE = #{requesterCode})
)

SELECT code AS room_code
FROM CHAT_ROOM
WHERE room_id = #{roomId}
